  const AIR_PTS = airWaypoints.map(([x, y]) => [100 * x + 50, 100 * y + 50]);

  function buildRoute(pts) {
    const segs = [];
    let total = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const [x0, y0] = pts[i];
      const [x1, y1] = pts[i + 1];
      const dx = x1 - x0;
      const dy = y1 - y0;
      const len = Math.abs(dx) + Math.abs(dy);
      segs.push({ x0, y0, ux: Math.sign(dx), uy: Math.sign(dy), start: total, len });
      total += len;
    }
    return { segs, total };
  }

  const GROUND_ROUTE = buildRoute(GROUND_PTS);
  const AIR_ROUTE = buildRoute(AIR_PTS);

  function posAt(route, progress) {
    let p = progress;
    for (let i = 0; i < route.segs.length; i++) {
      const s = route.segs[i];
      if (p <= s.start + s.len || i === route.segs.length - 1) {
        const d = p - s.start;
        return [s.x0 + s.ux * d, s.y0 + s.uy * d];
